// Winlink's public RMS PACTOR listing is plain text, one block per gateway channel:
//
//   K9BBS-10.WINLINK, Jerome Kutche/K9BBS, [EM68SR: Mitchell, IN], (Fri, 06 Oct 2017 23:03:00 GMT)
//   A Mitchell, IN
//   - 14112.5 14112.5# 18109.5 18109.5# 28181.5 28181.5#
//
// This is not an officially documented/versioned API (same situation as most
// Winlink tooling below the top-level web pages) -- if Winlink ever changes
// the listing text layout, only this regex needs updating.

var text = msg.payload || "";
var lines = text.split(/\r?\n/);

// Optional region filter: only keep gateways whose grid starts with one of
// these two-letter Maidenhead field prefixes. Leave the array empty to keep
// every station worldwide (the full PUBLIC list can be 100+ gateways).
// Example: ["EM", "FM"] keeps most of the southeastern/central US.
var gridPrefixFilter = [];

var headerRe = /^(\S+)\.WINLINK,\s*(.+?)\/(\S+),\s*\[([A-Za-z0-9]{4,6}):\s*([^\]]*)\],\s*\(([^)]+)\)\s*$/;

var stations = [];
var current = null;

for (var i = 0; i < lines.length; i++) {
    var line = lines[i].trim();
    var m = headerRe.exec(line);
    if (m) {
        if (current) { stations.push(current); }
        current = {
            channel: m[1],
            sysop: m[2].trim(),
            callsign: m[3].trim(),
            grid: m[4].toUpperCase(),
            location: m[5].trim(),
            lastUpdate: m[6].trim(),
            freqs: []
        };
        continue;
    }
    if (current) {
        if (line.indexOf("-") === 0) {
            var freqPart = line.replace(/^-\s*/, "");
            var freqTokens = freqPart.split(/\s+/).filter(Boolean);
            current.freqs = current.freqs.concat(freqTokens);
        } else if (line.indexOf("E ") === 0) {
            current.email = line.substring(2).trim();
        } else if (line.indexOf("H ") === 0) {
            current.homepage = line.substring(2).trim();
        }
        // "A " (address) lines are ignored -- duplicates the [Grid: ...] text
    }
}
if (current) { stations.push(current); }

if (gridPrefixFilter.length) {
    stations = stations.filter(function (s) {
        return gridPrefixFilter.indexOf(s.grid.substring(0, 2)) !== -1;
    });
}

node.status({ fill: "blue", shape: "dot", text: stations.length + " gateways parsed" });

var msgs = stations.map(function (s) {
    return { station: s };
});

return [msgs];

// ---- config -----------------------------------------------------------
// CoT type: friendly / Ground / Unit / Combat Support / Signal.
// This is the standard MIL-STD-2525 "Signal" (communications/network node)
// ground unit function. If your TAK client renders it differently than
// expected, this is the one line to change.
var cotType = "a-f-G-U-U-S";

// how long a marker stays on the map between polls before TAK greys it out
var staleHours = 20 / 60;
// -------------------------------------------------------------------------

function maidenheadToLatLon(loc) {
    loc = (loc || "").toUpperCase();
    if (loc.length < 4) { return null; }
    var A = "ABCDEFGHIJKLMNOPQR";
    var lon = (A.indexOf(loc[0]) * 20) - 180;
    var lat = (A.indexOf(loc[1]) * 10) - 90;
    lon += parseInt(loc[2], 10) * 2;
    lat += parseInt(loc[3], 10) * 1;
    if (loc.length >= 6) {
        lon += A.indexOf(loc[4]) * (2 / 24);
        lat += A.indexOf(loc[5]) * (1 / 24);
        lon += (2 / 24) / 2;
        lat += (1 / 24) / 2;
    } else {
        // center of the 4-character (locator) square
        lon += 1;
        lat += 0.5;
    }
    return { lat: lat, lon: lon };
}

function xmlEscape(s) {
    return (s || "").toString()
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;");
}

var s = msg.station;
if (!s || !s.grid) { return null; }

var pos = maidenheadToLatLon(s.grid);
if (!pos) { return null; }

var now = new Date();
var start = now.toISOString();
var stale = new Date(now.getTime() + staleHours * 60 * 60 * 1000).toISOString();

// each Winlink "channel" (e.g. K9BBS-10) is a distinct network node --
// one sysop callsign can run several channels on different frequencies/grids
var uid = "winlink-" + s.channel.replace(/[^A-Za-z0-9\-]/g, "_");

var remarksParts = ["Winlink RMS PACTOR gateway"];
if (s.freqs && s.freqs.length) { remarksParts.push("Freqs (kHz): " + s.freqs.join(" ")); }
remarksParts.push("Grid: " + s.grid + " (" + s.location + ")");
remarksParts.push("Last report: " + s.lastUpdate);
if (s.sysop) { remarksParts.push("Sysop: " + s.sysop + " (" + s.callsign + ")"); }
if (s.email) { remarksParts.push("Email: " + s.email); }

var cot = '<?xml version="1.0" encoding="UTF-8"?>' +
    '<event version="2.0" uid="' + uid + '" type="' + cotType + '" how="m-g" ' +
    'time="' + start + '" start="' + start + '" stale="' + stale + '">' +
    '<point lat="' + pos.lat.toFixed(6) + '" lon="' + pos.lon.toFixed(6) + '" hae="0" ce="9999999.0" le="9999999.0"/>' +
    '<detail>' +
    '<contact callsign="' + xmlEscape(s.channel) + '"/>' +
    '<remarks>' + xmlEscape(remarksParts.join(" | ")) + '</remarks>' +
    '</detail>' +
    '</event>';

msg.payload = cot;
delete msg.station;
return msg;

// Same plain-text block format as the PACTOR (HF) listing, just a different
// Winlink endpoint (RmsPacketListing.aspx instead of RmsPactorListing.aspx)
// covering VHF/UHF AX.25 packet / VARA FM gateways instead of HF PACTOR:
//
//   VE1HRE-10.WINLINK, Doug Steventon/VE1HRE, [FN84BQ: Halifax, NS], (...)
//   - 145.070 1200
//
// Not an officially documented/versioned API -- same caveat as the PACTOR
// listing. If Winlink changes the text layout, only this regex needs
// updating (kept identical to the PACTOR parser on purpose).

var text = msg.payload || "";
var lines = text.split(/\r?\n/);

// Optional region filter -- see the PACTOR parser for details. Empty = worldwide.
var gridPrefixFilter = [];

// VHF/UHF Packet listing uses '.RMS.PACKET' as the channel suffix, NOT
// '.WINLINK' like the HF/Pactor listing -- confirmed 2026-08-19 against a
// real fetched copy of this listing. This was the actual bug behind the
// "always 0 gateways" issue: the old regex only ever matched '.WINLINK'
// and this file never contains that string.
var headerRe = /^(\S+)\.RMS\.PACKET,\s*(.+?)\/(\S+),\s*\[([A-Za-z0-9]{4,6}):\s*([^\]]*)\],\s*\(([^)]+)\)\s*$/;

var stations = [];
var current = null;

for (var i = 0; i < lines.length; i++) {
    var line = lines[i].trim();
    var m = headerRe.exec(line);
    if (m) {
        if (current) { stations.push(current); }
        current = {
            channel: m[1],
            sysop: m[2].trim(),
            callsign: m[3].trim(),
            grid: m[4].toUpperCase(),
            location: m[5].trim(),
            lastUpdate: m[6].trim(),
            freqs: []
        };
        continue;
    }
    if (current) {
        if (line.indexOf("-") === 0) {
            var freqPart = line.replace(/^-\s*/, "");
            var freqTokens = freqPart.split(/\s+/).filter(Boolean);
            current.freqs = current.freqs.concat(freqTokens);
        } else if (line.indexOf("E ") === 0) {
            current.email = line.substring(2).trim();
        } else if (line.indexOf("H ") === 0) {
            current.homepage = line.substring(2).trim();
        }
    }
}
if (current) { stations.push(current); }

if (gridPrefixFilter.length) {
    stations = stations.filter(function (s) {
        return gridPrefixFilter.indexOf(s.grid.substring(0, 2)) !== -1;
    });
}

node.status({ fill: "green", shape: "dot", text: stations.length + " VHF/UHF gateways parsed" });

var msgs = stations.map(function (s) {
    return { station: s };
});

return [msgs];

// ---- config -----------------------------------------------------------
// Same symbol family as the HF/PACTOR branch: friendly / Ground / Unit /
// Combat Support / Signal. Change here if you want VHF/UHF gateways to
// render as a visibly different icon/color from the HF ones.
var cotType = "a-f-G-U-U-S";
var staleHours = 20 / 60;

// Tennessee + buffer bounding box -- VHF/UHF/Packet is short-range by
// nature (unlike HF/PACTOR, which stays worldwide), so gateways outside
// this box are dropped before ever reaching TAK Server. Same box already
// used for the Marinesia AIS flow, for consistency across these builds --
// adjust independently here if you want a different margin for radio vs. AIS.
var TN_BBOX = { latMin: 34.7, latMax: 37.0, lonMin: -90.6, lonMax: -81.3 };
// -------------------------------------------------------------------------

function maidenheadToLatLon(loc) {
    loc = (loc || "").toUpperCase();
    if (loc.length < 4) { return null; }
    var A = "ABCDEFGHIJKLMNOPQR";
    var lon = (A.indexOf(loc[0]) * 20) - 180;
    var lat = (A.indexOf(loc[1]) * 10) - 90;
    lon += parseInt(loc[2], 10) * 2;
    lat += parseInt(loc[3], 10) * 1;
    if (loc.length >= 6) {
        lon += A.indexOf(loc[4]) * (2 / 24);
        lat += A.indexOf(loc[5]) * (1 / 24);
        lon += (2 / 24) / 2;
        lat += (1 / 24) / 2;
    } else {
        lon += 1;
        lat += 0.5;
    }
    return { lat: lat, lon: lon };
}

function xmlEscape(s) {
    return (s || "").toString()
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;");
}

var s = msg.station;
if (!s || !s.grid) { return null; }

var pos = maidenheadToLatLon(s.grid);
if (!pos) { return null; }

// Drop anything outside the TN + buffer box -- this is the actual
// region limit for this branch now, applied against the real computed
// position rather than a coarse grid-prefix match.
if (pos.lat < TN_BBOX.latMin || pos.lat > TN_BBOX.latMax ||
    pos.lon < TN_BBOX.lonMin || pos.lon > TN_BBOX.lonMax) {
    return null;
}

var now = new Date();
var start = now.toISOString();
var stale = new Date(now.getTime() + staleHours * 60 * 60 * 1000).toISOString();

// prefixed "winlink-vhf-" (vs. "winlink-" for the HF/PACTOR branch) so a
// sysop running both a Pactor and a Packet channel doesn't collide on uid
var uid = "winlink-vhf-" + s.channel.replace(/[^A-Za-z0-9\-]/g, "_");

var remarksParts = ["Winlink RMS Packet (VHF/UHF) gateway"];
if (s.freqs && s.freqs.length) { remarksParts.push("Freq/baud: " + s.freqs.join(" ")); }
remarksParts.push("Grid: " + s.grid + " (" + s.location + ")");
remarksParts.push("Last report: " + s.lastUpdate);
if (s.sysop) { remarksParts.push("Sysop: " + s.sysop + " (" + s.callsign + ")"); }
if (s.email) { remarksParts.push("Email: " + s.email); }

var cot = '<?xml version="1.0" encoding="UTF-8"?>' +
    '<event version="2.0" uid="' + uid + '" type="' + cotType + '" how="m-g" ' +
    'time="' + start + '" start="' + start + '" stale="' + stale + '">' +
    '<point lat="' + pos.lat.toFixed(6) + '" lon="' + pos.lon.toFixed(6) + '" hae="0" ce="9999999.0" le="9999999.0"/>' +
    '<detail>' +
    '<contact callsign="' + xmlEscape(s.channel) + '"/>' +
    '<remarks>' + xmlEscape(remarksParts.join(" | ")) + '</remarks>' +
    '</detail>' +
    '</event>';

msg.payload = cot;
delete msg.station;
return msg;
